INSERT INTO `cards` (`id`, `category`, `title`, `description`, `image`, `pdf`, `created_at`) VALUES
(6, 'injectionmoulding', 'M9 Series – High Precision Servo Injection Molding Machine HW', 'The M9 Series offers advanced servo control for ultra-precise plastic molding. Built for manufacturers who value accuracy, energy efficiency, and reliability in every shot.', 'uploads/HM3.jpg', '', '2025-10-24 15:31:37'),
(22, 'injectionmoulding', 'SP Series – High Speed Plastic Injection Molding Machine HW', 'The SP Series ensures exceptional speed and stability for mass production. Perfect for industries requiring fast cycles, consistent quality, and reduced molding time.', 'uploads/HM2.jpg', '', '2025-10-27 20:26:22'),
(23, 'injectionmoulding', 'M8ⅡP Series – Performance Injection Molding Machine HW', 'The M8ⅡP Series delivers powerful, stable, and high-performance molding. Designed to handle versatile applications with efficiency and long-term durability.', 'uploads/HM1.jpg', '', '2025-10-27 20:26:58'),
(24, 'injectionmoulding', 'K5 Series Fixed Pump Injection Molding Machine SS', 'The SALLSEN K5 Series Injection Molding Machine delivers consistent performance with a controllable clamping force and high production efficiency.', 'uploads/SLS1.jpg', '', '2025-10-27 20:36:13'),
(25, 'injectionmoulding', '32 TON Micro Precise Injection Molding Machine (SSF320-G)', 'The SALLSEN SSF320-G Injection Molding Machine is engineered for micro-precision molding with stable performance and energy efficiency.', 'uploads/SLS2.jpg', '', '2025-10-27 20:36:44'),
(26, 'injectionmoulding', '100 Grams Plastic Injection Moulding Machine (SSF720-K5)', 'The SSF720-K5 delivers precise plastic injection moulding for small to medium components with a 100g shot capacity. Built for durability and energy efficiency, it ensures consistent high-quality production.', 'uploads/SLS3.jpg', '', '2025-10-27 20:37:10'),
(27, 'injectionmoulding', 'YZ 3S Medium Injection Molding Machines', 'Efficient YZ 3S Servo Motor Injection Molding Machine (320–650T) — perfect for manufacturing durable household products, food containers, and educational plastic items.', 'uploads/YZ3.webp', '', '2025-10-27 20:40:41'),
(28, 'injectionmoulding', 'YZ 3S Injeciton Moulding Machine', 'High-performance YZ 3S Servo Motor Injection Molding Machine (90–260T) — ideal for producing precision plastic parts for electronics, home appliances, and toys', 'uploads/YZ1.webp', '', '2025-10-27 20:41:39'),
(29, 'injectionmoulding', 'YZ 3S Large Injection Molding Machines youzu', 'Powerful YZ 3S Servo Motor Injection Molding Machine (850–1600T) — designed for producing large, high-precision plastic components for automotive, electronics, and industrial applications.', 'uploads/YZ2.webp', '', '2025-10-27 20:42:23'),
(31, 'lasercutting', 'Open Type Fiber Laser Sheet Cutting Machine (VS Series) ', 'The VS Series combines sheet and tube cutting in one versatile system, enhancing production flexibility and efficiency. Perfect for high-precision industrial cutting applications.', 'uploads/GS1.webp', '', '2025-10-27 21:11:31'),
(32, 'lasercutting', 'Eco-Friendly High-Speed Laser Sheet Cutting Machine (GS-CE Series)', 'The GS-CE Series delivers rapid, precise laser cutting with millisecond-level acceleration. Designed for energy efficiency and smooth operation in modern manufacturing environments.', 'uploads/GS2.webp', '', '2025-10-27 21:13:21'),
(33, 'lasercutting', 'GS-CE PRO SERIES – Ultra-High Power Fiber Laser Cutting Machine', 'Built for maximum stability and performance, this machine offers deformation resistance, smart collision detection, and an advanced fume extraction system for reliable and eco-friendly operation.', 'uploads/GS3.webp', '', '2025-10-27 21:19:05'),
(34, 'lasercutting', 'VS-CE SERIES – Cover Exchanged Fiber Laser Sheet Cutting Machine', 'Engineered for high efficiency and flexibility, the VS-CE Series features an exclusive collision detection system and space-saving design, ensuring safe, continuous, and precise production.', 'uploads/GS4.webp', '', '2025-10-27 21:19:37'),
(35, 'lasercutting', 'NS-CE SERIES – Ultra-High Power Fiber Laser Cutting Machine', 'Equipped with a dual-bed structure and full servo-driven system, the NS-CE Series delivers ultra-precise cutting and exceptional load capacity for heavy-duty industrial applications.', 'uploads/GS5.webp', '', '2025-10-27 21:20:08'),
(36, 'lasercutting', 'Uncoiling and Leveling Laser Cutting Line | GS-CF SERIES', 'Automatically feeds and levels coils for continuous, stable laser cutting.\r\nEnsures precise material supply with real-time monitoring and smooth operation.', 'uploads/GS6.webp', '', '2025-10-27 21:31:24'),
(37, 'lasercutting', 'Ultra-Large Format Unlimited Extension Fiber Laser Cutting Machine | GS-CL SERIES', 'Features an extra-large customizable bed for cutting massive metal sheets.\r\nSmart collision detection ensures safety with unmatched Z-axis travel and height capacity.', 'uploads/GS7.webp', '', '2025-10-27 21:31:55'),
(38, 'lasercutting', 'Fully Enclosed Side-Fed Fiber Laser Sheet Cutting Machine | GS-C SERIES', 'ompact and enclosed design for efficient, safe, and streamlined workshops.\r\nElectric worktable and safety sensors enhance ease of use and operator protection.', 'uploads/GS8.webp', '', '2025-10-27 21:32:24'),
(46, 'cncmachine', 'SYIL T7 Drill Tap Mill', '700x450x330 mm axis travels\\n21-pocket high-speed servo tool magazine\\n20,000 rpm direct BT30 spindle\\nHigh-precision mineral casting\\nTHK ball screw and linear guide', 'New folder/t7.jpg', 'pdf/t7.html', '2025-10-27 21:42:16'),
(48, 'cncmachine', 'SYIL X5 Mini CNC Mill', '300×260×300 mm axis travels\\n16-pocket high-speed servo tool changer\\n20,000 rpm direct-coupled BT30 spindle\\nSCHNEEBERGER mineral cast bed\\nOne-meter width for narrow spaces', 'New folder/x7/x5.png', 'x5.html', '2025-10-27 21:42:43'),
(49, 'cncmachine', 'SYIL X7 Small CNC Machinel', '400×300×380 mm axis travels\\n12-pocket umbrella automatic tool changer\\n12,000 rpm BT30 spindle\\nSCHNEEBERGER mineral casting', 'New folder/x7/x7.jpg', 'x7.html', '2025-10-27 21:42:43'),
(50, 'cncmachine', 'SYIL X9 Vertical Mill', '760×500×500 mm axis travels\\n24-pocket high-speed servo auto tool changer\\n10,000 rpm BT40 spindle\\nSCHNEEBERGER mineral casting', 'New folder/x7/x9.jpg', 'x9.html', '2025-10-27 21:42:43'),
(51, 'cncmachine', 'SYIL X11 Vertical Machining Center', '1000x500x500 mm axis travels\\n24-pocket high-speed servo auto tool changer\\n12,000 rpm BT40 spindle\\nSCHNEEBERGER mineral casting', 'New folder/x7/x11.jpg', 'x11.html', '2025-10-27 21:42:43'),
(52, 'cncmachine', 'SYIL L2 CNC Lathe', '8-inch hydraulic chuck\\nMaximum turning diameter of ø510 mm\\nThrough-hole diameter of ø66 mm\\n8-position servo tool turret\\nCompact footprint', 'New folder/l2.jpg', 'pdf/l2.html', '2025-10-27 21:42:43'),
(53, 'cncmachine', 'SYIL L3 CNC Lathe', '8-inch hydraulic chuck\\nMaximum swing diameter of ø500 mm\\nThrough-hole diameter of ø63 mm\\nA2-6 spindle\\nPower-driven tool speed of 5,000 rpm', 'New folder/l3.jpg', 'pdf/l3.html', '2025-10-27 21:42:43'),
(54, 'cncmachine', 'SYIL T5 Drill Tap Mill', '600x450x330 mm axis travels\\n21-pocket High-Speed Servo Tool Changer\\n20,000 rpm Direct BT30 Spindle\\nHigh-Precision Mineral Casting\\nTHK Ball Screw and Linear Guide', 'New folder/t5.jpg', 'pdf/t5.html', '2025-10-27 21:42:43'),
(56, 'cncmachine', 'SYIL U5 5-Axis Mill', '500x300x250 mm axis travels\\n200 mm Direct Drive 5-axis rotary table\\n32-pocket high-speed servo tool magazine\\n30,000 rpm HSK-E40 electric spindle\\nSCHNEEBEERGER mineral casting', 'New folder/u5.jpg', 'pdf/u5.html', '2025-10-27 21:42:43'),
(57, 'lasercutting', 'Fully Enclosed Side-Fed Fiber Laser Sheet Cutting Machine | GS-C SERIES', 'ompact and enclosed design for efficient, safe, and streamlined workshops.\r\nElectric worktable and safety sensors enhance ease of use and operator protection.', 'uploads/GS8.webp', '', '2025-10-27 21:43:40'),
