(68, 'laser_accessories', 'Ceramic Body', 'Essential component for stable and precise laser cutting head operation.', 'products/laser accessories/ceramic body.webp', '', '2025-10-27 22:02:56'),
(69, 'laser_accessories', 'Focus Lens', 'High-quality optical lens for concentrating the laser beam for optimal cut.', 'products/laser accessories/focus lens.avif', '', '2025-10-27 22:02:56'),
